// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** Partial update. Send `expected_version` (row_version you edited) to avoid overwriting another terminal's changes (409 VERSION_CONFLICT). A LabOnly patient becomes Regular by sending `upgrade_to_regular: true` with the required fields. */
export interface PatientUpdate {
  expected_version?: number | null;
  full_name?: string | null;
  gender?: "male" | "female" | "other" | "unknown" | null;
  dob?: string | null;
  age_years?: number | null;
  mobile?: string | null;
  cnic?: string | null;
  /** The Universal Patient Medical Record Number, once the PHC's HMIS issues one (announced for Category I hospitals; its format is not published yet): optional, unique among active records (PATIENT_UPMRN_EXISTS) */
  upmrn?: string | null;
  father_or_husband_name?: string | null;
  address?: string | null;
  emergency_contact_name?: string | null;
  emergency_contact_phone?: string | null;
  blood_group?: "A+" | "A-" | "B+" | "B-" | "AB+" | "AB-" | "O+" | "O-" | "Unknown" | null;
  allergies?: string | null;
  billing_category?: "Cash" | "Panel" | null;
  /** The panel (GET /finance/panels) */
  panel_id?: number | null;
  panel_member_no?: string | null;
  upgrade_to_regular?: boolean;
}

